class Solution:
    def countSubarrays(self, nums, k):
        n = len(nums)
        ans = 0
        for l in range(n):
            mx = mn = nums[l]
            for r in range(l, n):
                mx = max(mx, nums[r]); mn = min(mn, nums[r])
                if (mx - mn) * (r - l + 1) > k:
                    break
                ans += 1
        return ans

