public:
    int countSubarrays(vector<int>& nums, long long k) {
        int n = nums.size(); long long ans = 0; int l = 0;
        deque<int> mx, mn;
        for (int r = 0; r < n; r++) {
            while (!mx.empty() && nums[mx.back()] <= nums[r]) mx.pop_back();
            while (!mn.empty() && nums[mn.back()] >= nums[r]) mn.pop_back();
            mx.push_back(r); mn.push_back(r);
            while ((long long)(nums[mx.front()] - nums[mn.front()]) * (r - l + 1) > k) {
                l++;
                if (mx.front() < l) mx.pop_front();
                if (mn.front() < l) mn.pop_front();
            }
            ans += r - l + 1;
        }
        return (int) ans;
    }
};

